export const DEFAULT_STABLE_SUPPORTED_EXTENSIONS = Object.freeze(Array.from(new Set(DEFAULT_RENDERER_DEFINITIONS
    .filter(definition => definition.status === 'stable')
    .flatMap(definition => definition.extensions))).sort());
